export const EXTRA_QUESTIONS: ExtraQ[] = E

/** Build full Question objects from compact extras, assigning module ids the
 * same way the catalog engine does (domain index → module bucket). */
export function buildExtraQuestions(tracks: CredentialTrack[]): Question[] {
  const out: Question[] = []
  const counters = new Map<string, number>()
  for (const e of EXTRA_QUESTIONS) {
    const track = tracks.find((t) => t.id === e.trackId)
    const short = e.trackId.replace(/^track_/, '')
    const n = (counters.get(e.trackId) ?? 0) + 1
    counters.set(e.trackId, n)
    const domains = track?.domains ?? []
    const di = Math.max(0, domains.indexOf(e.domain))
    const modIdx = Math.min(9, Math.floor((di * 10) / Math.max(1, domains.length)))
    out.push({
      id: `q_${short}_x${String(n).padStart(2, '0')}`,
      trackId: e.trackId,
      moduleId: `mod_${short}_${String(modIdx + 1).padStart(2, '0')}`,
      topic: e.domain,
      type: e.type ?? 'multiple_choice',
      difficulty: e.difficulty,
      text: e.q,
      choices: e.choices,
      correctIndex: e.answer,
      explanation: e.why,
      estimatedTimeSec: e.difficulty === 'hard' ? 60 : e.difficulty === 'medium' ? 45 : 35,
      tags: [e.domain.toLowerCase().replace(/[^a-z0-9]+/g, '-'), e.trackId],
      wrongRationales: e.wrongRationales,
      correctIndexes: e.correctIndexes,
      sequenceItems: e.sequenceItems,
      pairs: e.pairs,
      numericAnswer: e.numericAnswer,
      keywords: e.keywords,
      caseStem: e.caseStem,
      weight: e.weight ?? (e.difficulty === 'hard' ? 2 : e.difficulty === 'medium' ? 1.5 : 1),
    })
  }
  return out
}
